def compute(vars):
    total = vars["v1"] + vars["v2"]
    return {
        "value": total,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "sum": total,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency/share"
            }
        }
    }
